messages.content:
  1→/**
  2→ * 一个 token 只有在**别处不存在**的时候,才能证明"内容来自这个资产"。
  3→ *
  4→ * 旧口径的 token 是部署地址(`10.244.7.19`、端口 `47318`)。它高不高熵是次要的,
  5→ * 要害是**来源不唯一**:地址写在资产里,也写在记忆基线里、写在模型自己发出的
  6→ * curl 命令行里、还能从部署环境读出来。命中一次 token 并不说明读了资产。
  7→ *
  8→ * 所以换 token 之前先跑这个检查:候选值是否已经出现在任务说明、池内其他资产、
  9→ * 系统提示、历史记忆基线、或任何缓存里。**高熵本身不保证来源唯一。**
 10→ */
 11→import { test } from "node:test";
 12→import assert from "node:assert/strict";
 13→import { scanSources, provenanceOf, isDerivableFromDeployment } from "./token-provenance.mjs";
 14→
 15→const src = (name, kind, text) => ({ name, kind, text });
 16→
 17→test("token 出现在任何一个来源里,就不算干净", () => {
 18→  const sources = [
 19→    src("task.md", "task", "reach the bridge and report"),
 20→    src("baseline/persona.md", "memory", "上次用 47318 成功了"),
 21→  ];
 22→  const v = provenanceOf("47318", sources);
 23→  assert.equal(v.clean, false);
 24→  assert.deepEqual(v.found_in.map((f) => f.kind), ["memory"]);
 25→});
 26→
 27→test("哪个来源命中要报出来,不能只说不干净", () => {
 28→  const sources = [
 29→    src("assets/right.md", "asset", "port 47318"),
 30→    src("assets/wrong.md", "asset", "port 8096"),
 31→    src("system-prompt", "system", "you are a CLI"),
 32→  ];
 33→  const v = provenanceOf("47318", sources);
 34→  assert.equal(v.clean, false);
 35→  assert.deepEqual(v.found_in.map((f) => f.name), ["assets/right.md"]);
 36→});
 37→
 38→test("本资产自己的正文不算污染——那正是它该在的地方", () => {
 39→  const sources = [src("assets/right.md", "self", "marker rk-abc123")];
 40→  const v = provenanceOf("rk-abc123", sources);
 41→  assert.equal(v.clean, true, "kind=self 的来源要排除在外");
 42→});
 43→
 44→test("完全没出现过 → 干净", () => {
 45→  const v = provenanceOf("rk-deadbeef", [src("task.md", "task", "reach the bridge")]);
 46→  assert.equal(v.clean, true);
 47→  assert.deepEqual(v.found_in, []);
 48→});
 49→
 50→test("匹配不区分大小写,且要能穿过被切开的写法", () => {
 51→  // FTS5 的 snippet 会在标点处切分并补空格;被切开的 token 仍然是 token。
 52→  const sources = [src("cache", "cache", "value RK- ABC123 was returned")];
 53→  const v = provenanceOf("rk-abc123", sources);
 54→  assert.equal(v.clean, false, "切开的写法也要算命中");
 55→});
 56→
 57→// ---------------------------------------------------------------------------
 58→// 可从部署环境推导 —— 高熵挡不住的那一类
 59→// ---------------------------------------------------------------------------
 60→
 61→test("地址形状的值一律拒绝:它可以从部署环境读出来", () => {
 62→  for (const bad of ["10.244.7.19", "47318", "127.0.0.1", "8096", "10.244.7.19:8096"]) {
 63→    assert.equal(isDerivableFromDeployment(bad), true, `${bad} 应被判为可从环境推导`);
 64→  }
 65→});
 66→
 67→test("随机标记不可从部署环境推导", () => {
 68→  for (const ok of ["rk-9f2c1ab77e04", "mk-0a1b2c3d4e5f6071"]) {
 69→    assert.equal(isDerivableFromDeployment(ok), false, `${ok} 不应被判为可推导`);
 70→  }
 71→});
 72→
 73→test("太短的值即使随机也拒绝:短串会撞上无关数字", () => {
 74→  assert.equal(isDerivableFromDeployment("ab12"), true, "长度不足,区分度无从谈起");
 75→});
 76→
 77→test("scanSources 逐个来源返回命中次数", () => {
 78→  const hits = scanSources("rk-abc", [
 79→    src("a", "memory", "rk-abc rk-abc"),
 80→    src("b", "task", "none here"),
 81→  ]);
 82→  assert.equal(hits.length, 1);
 83→  assert.equal(hits[0].name, "a");
 84→  assert.equal(hits[0].count, 2);
 85→});
 86→
 87→// ---------------------------------------------------------------------------
 88→// 扫不到 ≠ 没有 —— 2026-09-09 独立审阅 D3 / D4
 89→// ---------------------------------------------------------------------------
 90→import { mkdtempSync, writeFileSync, mkdirSync } from "node:fs";
 91→import { tmpdir } from "node:os";
 92→import { join } from "node:path";
 93→import { sourcesFromRun, readTextFilesUnder } from "./token-provenance.mjs";
 94→
 95→test("捕获首行解析不出来 → 记为问题,不静默算 0 来源", () => {
 96→  const d = mkdtempSync(join(tmpdir(), "prov-"));
 97→  writeFileSync(join(d, "capture.jsonl"), '{"event":"http.request","body":{BROKEN');
 98→  const r = sourcesFromRun(d);
 99→  // 整目录扫描会把 capture.jsonl 本身按 record 算一处来源;要害是解析失败被说出来。
100→  assert.ok(!r.sources.some((s) => s.kind === "system" || s.kind === "memory"), "首个请求没解析出来,就不该有 system/memory 来源");
101→  assert.equal(r.problems.length, 1, "读不出来必须说出来,否则会被当成扫过了");
102→  assert.match(r.problems[0].why, /解析/);
103→});
104→
105→test("坏行不阻断后面的:第一条能解析的请求才算数", () => {
106→  const d = mkdtempSync(join(tmpdir(), "prov-"));
107→  const good = JSON.stringify({ event: "http.request", body: { messages: [{ role: "system", content: "港口 47318" }] } });
108→  writeFileSync(join(d, "capture.jsonl"), `{"event":"http.request","body":{BROKEN\n${good}\n`);
109→  const r = sourcesFromRun(d);
110→  assert.equal(r.sources.filter((s) => s.kind === "system").length, 1, "后面那条是好的,应该被读到");
111→  assert.equal(r.problems.length, 0, "有能解析的行就不算问题");
112→});
113→
114→test("捕获文件存在但一条请求都读不出 → 也是问题", () => {
115→  const d = mkdtempSync(join(tmpdir(), "prov-"));
116→  writeFileSync(join(d, "capture.jsonl"), '{"event":"http.response","body":{}}\n');
117→  const r = sourcesFromRun(d);
118→  assert.equal(r.problems.length, 1);
119→});
120→
121→test("超过大小上限的文件记为未扫描,不是不存在", () => {
122→  const d = mkdtempSync(join(tmpdir(), "prov-"));
123→  mkdirSync(join(d, "sub"), { recursive: true });
124→  writeFileSync(join(d, "sub", "huge.md"), "x".repeat(500) + " 47318");
125→  const r = readTextFilesUnder(d, "memory", 100);
126→  assert.equal(r.files.length, 0, "确实没读");
127→  assert.equal(r.skipped.length, 1, "但必须报出来,不能当作扫过了");
128→  assert.ok(r.skipped[0].bytes > 100);
129→});
130→
131→test("运行目录不存在 → 明确报缺输入,不是 0 来源 0 问题", () => {
132→  const r = sourcesFromRun("/tmp/definitely-not-a-run-dir-9f31");
133→  assert.equal(r.sources.length, 0);
134→  assert.equal(r.problems.length, 1, "指定了却不存在,是缺输入,不是扫过了没有");
135→  assert.match(r.problems[0].why, /不存在/);
136→});
137→
138→test("捕获文件缺失 → 也是缺输入", () => {
139→  const d = mkdtempSync(join(tmpdir(), "prov-"));
140→  const r = sourcesFromRun(d);
141→  assert.equal(r.problems.length, 1);
142→  assert.match(r.problems[0].why, /capture\.jsonl/);
143→});
144→
145→// ---------------------------------------------------------------------------
146→// 任务目录里哪些文件是模型看得到的 —— 2026-09-10
147→//
148→// tokens.json、pair.json、测试文件、条件清单都写着 token,但它们是评测的记录,
149→// 不会交给会话。把它们当污染源,新 token 永远通不过来源检查;把它们静默跳过,
150→// 又会掩盖真正的泄漏。所以分三类并写明:self(资产正文,token 的家)、record
151→// (评测记录,不交给会话——前提是会话在空目录里跑,由 run-once.sh 保证)、task
152→// (任务说明等,会交给会话,命中即污染)。
153→// ---------------------------------------------------------------------------
154→import { taskFileKind } from "./token-provenance.mjs";
155→
156→test("资产正文是 self,任务说明是 task,评测记录是 record", () => {
157→  assert.equal(taskFileKind("assets/right.md"), "self");
158→  assert.equal(taskFileKind("task.md"), "task");
159→  assert.equal(taskFileKind("tokens.json"), "record");
160→  assert.equal(taskFileKind("pair.json"), "record");
161→  assert.equal(taskFileKind("verify.test.mjs"), "record");
162→  assert.equal(taskFileKind("README.md"), "record");
163→  assert.equal(taskFileKind("confounders.watch"), "record");
164→  assert.equal(taskFileKind("verify.mjs"), "record");
165→});
166→
167→test("record 也算污染:冒烟运行里模型 cat 到了 tokens.json", () => {
168→  // 2026-09-10 上午的版本把 record 排除在污染之外,前提是仓库不可及;同日下午的
169→  // 冒烟运行证明模型能从进程表找到仓库并读这些文件。分类只用于报告,不用于豁免。
170→  const sources = [
171→    { name: "task:tokens.json", kind: "record", text: '{"tokens":["bt-abc123xyz9"]}' },
172→    { name: "task:task.md", kind: "task", text: "无关内容" },
173→  ];
174→  const v = provenanceOf("bt-abc123xyz9", sources);
175→  assert.equal(v.clean, false, "写在磁盘上模型可读的地方,就不是唯一来源");
176→  assert.deepEqual(v.found_in.map((f) => f.kind), ["record"], "报告里要说明命中的是评测记录");
177→});
178→
179→test("只有资产正文自己(self)不算污染", () => {
180→  const sources = [{ name: "task:assets/right.md", kind: "self", text: "x-team-trace: bt-abc123xyz9" }];
181→  assert.equal(provenanceOf("bt-abc123xyz9", sources).clean, true);
182→});
183→
184→// ---------------------------------------------------------------------------
185→// 运行记录要整目录扫,不只首个请求 —— 2026-09-11 审阅
186→//
187→// 反例:trace 只出现在后续工具结果里、或只在 verdict.json 里,sourcesFromRun 仍报
188→// clean。暂存目录还多一层父目录,按直接子目录找抓包会漏。
189→// ---------------------------------------------------------------------------
190→import { sourcesFromRecordsRoot } from "./token-provenance.mjs";
191→
192→const reqLine = (msgs) => JSON.stringify({ event: "http.request", body: { json: { messages: msgs } } });
193→const mkRun = (dir, { later, verdict } = {}) => {
194→  mkdirSync(dir, { recursive: true });
195→  const lines = [reqLine([{ role: "system", content: "无关" }])];
196→  if (later) lines.push(reqLine([{ role: "system", content: "无关" }, { role: "tool", content: `Stdout: trace ${later}` }]));
197→  writeFileSync(join(dir, "capture.jsonl"), lines.join("\n") + "\n");
198→  if (verdict) writeFileSync(join(dir, "verdict.json"), JSON.stringify({ attempts: [{ value: verdict }] }));
199→};
200→
201→test("trace 只在后续请求的工具结果里 → 也要命中", () => {
202→  const d = mkdtempSync(join(tmpdir(), "prov-")); mkRun(d, { later: "bt-laterval99" });
203→  const r = sourcesFromRun(d);
204→  assert.equal(provenanceOf("bt-laterval99", r.sources).clean, false);
205→});
206→
207→test("trace 只在 verdict.json 里 → 也要命中", () => {
208→  const d = mkdtempSync(join(tmpdir(), "prov-")); mkRun(d, { verdict: "bt-verdictval9" });
209→  const r = sourcesFromRun(d);
210→  assert.equal(provenanceOf("bt-verdictval9", r.sources).clean, false);
211→});
212→
213→test("记录根下多一层暂存父目录,整棵树都要扫到", () => {
214→  const root = mkdtempSync(join(tmpdir(), "prov-root-"));
215→  mkRun(join(root, "20260911T000000Z-x.AbCd", "20260911T000000Z-x"), { verdict: "bt-nestedval99" });
216→  const r = sourcesFromRecordsRoot(root);
217→  assert.equal(provenanceOf("bt-nestedval99", r.sources).clean, false);
218→  assert.equal(r.problems.length, 0);
219→});
220→

freshness.description:
Filter search results by time range. Supports d[N], m[N], and y[N] for the last N calendar days, months, and years:
- d[N]: N is an integer from 1 to 30;
- m[N]: N is an integer from 1 to 12;
- y[N]: N is an integer from 1 to 5.

N may be omitted and defaults to 1. The current partial calendar unit counts as 1. For example, d1 means today, m1 means the current month to date, and y1 means the current year to date. Omit this parameter to disable time filtering.

