```js
function asEnvelope(res, bytes) {
  // The envelope is what the download branch returns for an error or for an
  // empty resource; a real resource comes back as raw bytes. JSON is the
  // discriminator: the envelope is an object carrying a numeric `code`.
  const looksJson = JSON_CT.test(res?.headers?.get?.("content-type") ?? "");
