```js
async function readResponse(res) {
  if (typeof res?.arrayBuffer === "function") return { bytes: Buffer.from(await res.arrayBuffer()) };
  if (typeof res?.text === "function") return { bytes: Buffer.from(await res.text(), "utf-8") };
